content:
/*
 * Synthetic syntax-only harness for the CVE-2018-10882 port.
 *
 * This does NOT build the kernel. It stubs the minimal types/macros (mirroring
 * the real field ownership: s_es and s_first_ino live in struct ext4_sb_info,
 * s_inodes_count and s_first_ino live in struct ext4_super_block) and embeds
 * the three edited constructs verbatim so gcc can check that the modified
 * expressions are syntactically and type-wise well formed.
 * It is recorded as a syntax check, not as a module build.
 */
typedef unsigned int __u32;
typedef unsigned int __le32;

struct ext4_super_block {
	__le32 s_inodes_count;
	__le32 s_first_ino;
};

struct ext4_sb_info {
	struct ext4_super_block *s_es;
	int s_first_ino;
};

struct super_block {
	void *s_fs_info;
};

struct inode {
	unsigned long i_ino;
	struct super_block *i_sb;
};

#define EXT4_ROOT_INO 2
#define EXT4_FIRST_INO(sb) (EXT4_SB(sb)->s_first_ino)
#define EXT4_GOOD_OLD_FIRST_INO 11
#define EXT4_GOOD_OLD_INODE_SIZE 128
#define EXT4_SB(sb) ((struct ext4_sb_info *)((sb)->s_fs_info))
#define KERN_ERR ""

static __u32 le32_to_cpu(__le32 v) { return v; }
static void ext4_msg(struct super_block *sb, const char *level,
		     const char *fmt, ...) { (void)sb; (void)level; (void)fmt; }
static void failed_mount_label(void) {}

/* CU-001: ext4_valid_inum after the fix (verbatim body) */
static inline int ext4_valid_inum(struct super_block *sb, unsigned long ino)
{
	return ino == EXT4_ROOT_INO ||
		(ino >= EXT4_FIRST_INO(sb) &&
		 ino <= le32_to_cpu(EXT4_SB(sb)->s_es->s_inodes_count));
}

/* CU-002: the replaced guard (verbatim) */
static int check_inode_loc(struct inode *inode)
{
	int ret = 0;

	if (inode->i_ino < EXT4_ROOT_INO ||
	    inode->i_ino > le32_to_cpu(EXT4_SB(inode->i_sb)->s_es->s_inodes_count))
		ret = -5; /* -EIO */
	return ret;
}

/* CU-003: the inserted mount check (verbatim shape) */
static int mount_check(struct super_block *sb, struct ext4_sb_info *sbi,
		       struct ext4_super_block *es)
{
	int blocksize = 1024;
	int s_inode_size;

	s_inode_size = es->s_first_ino ? (int)es->s_first_ino : 256;
	sbi->s_first_ino = le32_to_cpu(es->s_first_ino);
	if (sbi->s_first_ino < EXT4_GOOD_OLD_FIRST_INO) {
		ext4_msg(sb, KERN_ERR, "invalid first ino: %u",
			 sbi->s_first_ino);
		goto failed_mount;
	}
	if ((s_inode_size < EXT4_GOOD_OLD_INODE_SIZE) || blocksize == 0)
		goto failed_mount;
	return 0;
failed_mount:
	failed_mount_label();
	return -5;
}

int main(void)
{
	struct ext4_super_block es = {0};
	struct ext4_sb_info sbi = {.s_es = &es};
	struct super_block sb = {.s_fs_info = &sbi};
	struct inode inode = {.i_ino = 8, .i_sb = &sb};

	(void)ext4_valid_inum(&sb, 8);
	(void)check_inode_loc(&inode);
	(void)mount_check(&sb, &sbi, &es);
	return 0;
}

